#!/usr/bin/env python3
"""Auditoria independente: recalcula os marcos de prazos.json a partir da
tabela do calendário da biblioteca e confere rótulos de dia da semana nos
entregáveis. Não usa os números já escritos nos entregáveis para calcular."""
import json, re, sys
from datetime import date, timedelta

LIB = "/work/workspace/library/calendario_forense_campinas.md"
DEL = "/work/workspace/deliverable"

WD = {"seg": 0, "ter": 1, "qua": 2, "qui": 3, "sex": 4, "sáb": 5, "sab": 5, "dom": 6}
WD_FULL = {0: "seg", 1: "ter", 2: "qua", 3: "qui", 4: "sex", 5: "sáb", 6: "dom"}

# 1) Parse da tabela do calendário
txt = open(LIB, encoding="utf-8").read()
holidays, capital_only = set(), set()
for line in txt.splitlines():
    m = re.match(r"\|\s*(\d{2})/(\d{2})/(\d{4})\s*\((\w+)\)\s*\|\s*(.+?)\s*\|", line)
    if not m:
        continue
    d = date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
    if "APENAS na Capital" in m.group(5):
        capital_only.add(d)  # não é feriado em Campinas
    else:
        holidays.add(d)
m = re.search(r"20/12/(\d{4})\s*a\s*20/01/(\d{4}),\s*inclusive", txt)
assert m, "suspensão não encontrada"
susp_ini = date(int(m.group(1)), 12, 20)
susp_fim = date(int(m.group(2)), 1, 20)

def util(d):
    return d.weekday() < 5 and d not in holidays and not (susp_ini <= d <= susp_fim)

def prox_util(d):
    d += timedelta(days=1)
    while not util(d):
        d += timedelta(days=1)
    return d

def venc(inicio, n):  # exclui começo, inclui vencimento; dia 1 = 1º útil após início
    d, k = inicio, 0
    while k < n:
        d = prox_util(d)
        k += 1
    return d

def f(d): return d.isoformat()

# 2) Recálculo
cit_pub = prox_util(date(2026, 11, 19))
cit_ini = prox_util(cit_pub)
cit_venc = venc(cit_ini, 15)
sen_pub = prox_util(date(2026, 12, 10))
sen_ini = prox_util(sen_pub)
emb_venc = venc(sen_ini, 5)
ape_venc = venc(sen_ini, 15)

esperado = {
    "citacao": {"disponibilizacao": "2026-11-19", "publicacao": f(cit_pub),
                "inicio_contagem": f(cit_ini), "contestacao_vencimento": f(cit_venc)},
    "sentenca": {"disponibilizacao": "2026-12-10", "publicacao": f(sen_pub),
                 "inicio_contagem": f(sen_ini), "embargos_vencimento": f(emb_venc),
                 "apelacao_vencimento": f(ape_venc)},
}
pj = json.load(open(f"{DEL}/prazos.json", encoding="utf-8"))
erros = []
for bloco, chaves in esperado.items():
    for k, v in chaves.items():
        got = pj[bloco].get(k)
        if got != v:
            erros.append(f"JSON {bloco}.{k}: esperado {v}, obtido {got}")
        else:
            print(f"OK  {bloco}.{k} = {v} ({WD_FULL[date.fromisoformat(v).weekday()]})")
if pj["citacao"].get("prazo_em_dobro") is not False:
    erros.append("prazo_em_dobro != false")

# 3) Rótulos de dia da semana nos .md (padrões "xx dd/mm/aaaa" e "dd/mm/aaaa (xx)")
pad = re.compile(r"(seg|ter|qua|qui|sex|sáb|sab|dom)\s+(\d{2})/(\d{2})/(\d{4})"
                 r"|(\d{2})/(\d{2})/(\d{4})\s*\((seg|ter|qua|qui|sex|sáb|sab|dom)\)")
rotulos = 0
for nome in ["memoria.md", "STATUS.md", "QUESTIONS.md"]:
    t = open(f"{DEL}/{nome}", encoding="utf-8").read()
    for mm in pad.finditer(t):
        rotulos += 1
        if mm.group(1):
            lab, d = mm.group(1), date(int(mm.group(3)), int(mm.group(2)), int(mm.group(4)))
        else:
            lab, d = mm.group(7), date(int(mm.group(6)), int(mm.group(5)), int(mm.group(4)))
        real = WD_FULL[d.weekday()]
        if WD[lab.lower()] != d.weekday():
            erros.append(f"{nome}: rótulo '{lab} {d.strftime('%d/%m/%Y')}', real={real}")
print(f"rótulos de dia da semana verificados: {rotulos}")

if erros:
    print("\nERROS:"); [print(" -", e) for e in erros]; sys.exit(1)
print("AUDITORIA: tudo confere.")

